"""Additional lessons in phases 1 and 3."""
DATA=[
('1.7','滑动窗口与哈希表','LeetCode 3','查找最长不含重复字符的连续子串。','right 逐个加入字符；如果字符曾在当前窗口出现，把 left 移到它上次位置的下一位。记录每个字符最近下标；left 不能后退。','平均时间 O(n)，额外空间 O(min(n,字符集大小))；C++ 示例按单字节字符处理，不直接适用于 UTF-8 中文字符。', ['abcabcbb','窗口 abc：长度 3','遇到重复 a，左边界移到 1','最终最大长度 3'], '手算 abba，注意 left 不能后退。','用 max(left, 上次下标+1)，不要直接覆盖 left。'),
('1.8','排序算法','排序入门','让一组数字按升序排列，为二分查找或后续处理做准备。','冒泡相邻交换；插入把新元素放入有序前缀；归并合并有序区间；快排围绕基准划分。下面演示插入排序。','插入排序最坏 O(n²)、额外 O(1)，稳定；归并排序 O(n log n)、数组实现通常额外 O(n)，可稳定；快排平均 O(n log n)、最坏 O(n²)，常见实现不稳定且递归栈额外占用。', ['5 2 4 1','插入 2：2 5 4 1','插入 4：2 4 5 1','插入 1：1 2 4 5'], '手算 [4,1,3,2] 的每轮有序前缀。','空数组和单元素无需移动；稳定性讨论的是相等键的相对顺序。'),
('3.1','递归 DFS','深度优先搜索','在路网中先沿一条路走到不能再走，再返回岔路。','进入节点先标记，再递归访问每个未访问的邻居；需要覆盖不连通图时，从每个未访问节点重新启动。','邻接表遍历时间 O(V+E)，visited 和递归栈最坏各 O(V)。递归深度过大可能溢出。', ['访问 A','A → B','B → D，返回 B','返回 A，访问 C'], '写出从 A 出发的访问顺序并比较邻居顺序改变后的结果。','DFS 的访问顺序取决于邻接表顺序。'),
('3.2','非递归 DFS','显式栈','用容器模拟递归调用时的待处理任务。','使用栈存放待访问节点；弹出后处理，把未访问邻居按需要压栈。实现方式不同可能得到不同合法访问顺序。','邻接表 O(V+E)，栈及标记 O(V)；入栈即标记可避免重复入栈。', ['栈 [A]','弹出 A，加入 C、B','弹出 B，加入 D','继续直到栈为空'], '比较递归 DFS 与显式栈顺序。','栈后进先出；想先处理某邻居，要考虑压栈顺序。'),
('3.3','DFS 与回溯','路径枚举','探索一条路线后撤销选择，继续尝试其他路线。','将当前节点放进路径并标记；搜索相邻节点；返回后弹出并撤销路径标记，以允许其他路径使用该节点。','枚举所有简单路径在最坏情况下可呈指数或阶乘级增长，取决于图结构；空间包括当前路径与标记。', ['路径 [A]','路径 [A,B]','到达目标：保存 [A,B,D]','撤销 B，继续 A→C'], '在 A→B、A→C、B→D、C→D 中列出所有路径。','枚举简单路径用路径内标记；普通连通性遍历的全局标记通常不撤销。'),
('3.4','队列 BFS','广度优先搜索','先探索离起点一步的位置，再探索两步的位置。','起点入队并立即标记；每次出队一个节点，把未发现的邻居标记后入队。','邻接表时间 O(V+E)，队列和 visited 最坏 O(V)。', ['队列 [A]','弹出 A，加入 B、C','弹出 B，加入 D','依次弹出 C、D'], '在 A—B、A—C、B—D 中写出每一步队列。','标记放在入队时，可防止多个父节点重复入队。'),
('3.5','树的层序遍历','层序遍历','按深度逐层查看树上的节点。','队列中每轮开始时的长度就是当前层节点数；处理固定数量后，队列中留下下一层。','每个节点进出队一次，时间 O(n)，队列空间与最大层宽有关，最坏 O(n)。', ['第一层 [1]','第二层 [2,3]','第三层 [4,5]'], '画出根 1、子节点 2 和 3、2 的子节点 4 的层序结果。','每轮先保存队列长度，不能用动态变化的长度作为本层循环次数。'),
('3.6','无权图最短路径','BFS 最短路','在每条路代价相同的地图上寻找经过边数最少的路径。','BFS 首次发现节点时记录距离与前驱；到达终点后沿前驱反向回溯得到路径。','邻接表时间 O(V+E)，距离、前驱和队列 O(V)。仅在无权或所有边等权且权值相同的情况下，边数最少等价于代价最小。', ['从 A 出发，距离 0','B、C 距离 1','D 距离 2','前驱回溯：A→B→D'], '构造 A—B—D 与 A—C—D，两条最短路长度是多少？','无法到达时返回空路径；存在多条最短路时顺序影响返回哪一条。'),
('3.7','二维地图 DFS','网格搜索','在有障碍物的栅格中判断起点能否到达终点。','对上下左右四个邻居依次检查边界、障碍和访问标记，再继续深入。','R×C 网格中时间 O(RC)，访问标记及递归栈最坏 O(RC)。','起点 (0,0)|访问相邻通路|遇到障碍就回退|到达终点或搜索结束'.split('|'), '在 3×4 地图中手动标记访问格子。','先检查边界再访问数组；DFS 找到的路径不一定最短。'),
('3.8','二维地图 BFS 与对比','网格最短路','在四方向、每步代价相同的地图中找最少步数。','用队列按层访问通路，本课代码记录距离；若需要还原路径，还需在发现邻居时记录前驱，再从终点回溯。','R×C 网格，时间 O(RC)、额外空间 O(RC)。若方向移动代价不同，要使用适合带权图的算法。', ['起点距离 0','相邻通路距离 1','下一层距离 2','首次抵达终点即为最短步数'], '对比 DFS 找到的一条路和 BFS 的最短步数。','先检查起终点可通行，若不可达返回 -1；不允许斜向移动。')]

def make_lesson(row):
 id,title,tag,intuition,rules,complexity,steps,exercise,hint=row
 frames=[([str(x) for x in steps[:i+1]],step,[i]) for i,step in enumerate(steps)]
 return (id,title,tag,intuition,rules,complexity,frames,'完整的 C++ 与 Python 程序请查看左侧「完整代码」。',exercise,hint)
LESSONS=[make_lesson(x) for x in DATA]
